-- Longe & Perto — músicas da Trilha da rodada, extraídas das playlists do Ricardo.
-- Rode DEPOIS do 004_v3.sql. Pode rodar de novo: o ajuste é idempotente e faixas repetidas no mesmo nível são ignoradas.

-- ---------------------------------------------------------------------------
-- Ajuste da tabela musicas para o seed: coluna playlist e títulos/artistas de até 200 caracteres.
alter table public.musicas add column if not exists playlist text;

-- Remove os limites antigos de tamanho de titulo e artista, quaisquer que sejam os nomes das constraints
do $$
declare r record;
begin
  for r in
    select conname from pg_constraint
    where conrelid = 'public.musicas'::regclass
      and contype = 'c'
      and (pg_get_constraintdef(oid) ilike '%titulo%' or pg_get_constraintdef(oid) ilike '%artista%')
  loop
    execute format('alter table public.musicas drop constraint %I', r.conname);
  end loop;
end $$;

alter table public.musicas
  add constraint musicas_titulo_tamanho  check (char_length(btrim(titulo))  between 1 and 200),
  add constraint musicas_artista_tamanho check (char_length(btrim(artista)) between 1 and 200);

